import numpy as np
def solve_1d_conduction(L, n, T_left, T_right, k):
    A = np.zeros((n, n)); b = np.zeros(n)
    A[0,0]=1.0; b[0]=T_left; A[-1,-1]=1.0; b[-1]=T_right
    for i in range(1, n-1):
        A[i,i-1]=1.0; A[i,i]=-2.0; A[i,i+1]=1.0; b[i]=0.0
    return list(np.linalg.solve(A, b))

import numpy as np
def solve_conduction_with_source(L, n, T_left, T_right, k, q_gen):
   dx = L/(n-1)
   A = np.zeros((n, n)); b = np.zeros(n)
   A[0,0] = 1.0; b[0] = T_left
   A[-1,-1] = 1.0; b[-1] = T_right
   for i in range(1, n-1):
       A[i, i-1] = 1.0; A[i, i] = -2.0; A[i, i+1] = 1.0
       b[i] = -q_gen*dx*dx/k
   return list(np.linalg.solve(A, b))

import math
def lmtd_hx(dT1, dT2):
   ans = dT1
   if abs(dT1 - dT2) < 1e-9:
       ans = dT1
   else:
       ans = (dT1 - dT2)/math.log(dT1/dT2)
   return ans
